GORSELLER = {'b1': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="16" fill="#f8fafc"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="700" fill="#1e3a8a">Wishes and Time: Past Regret vs. Present Wish</text><rect x="40" y="52" width="320" height="150" rx="12" fill="#ffffff" stroke="#dc2626" stroke-width="2"/><rect x="40" y="52" width="320" height="30" rx="12" fill="#dc2626"/><text x="200" y="72" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Past Regret (Geçmişe Dönük Pişmanlık)</text><text x="56" y="104" font-size="12" fill="#7f1d1d">Fact: I didn\'t ask for help last term.</text><text x="56" y="128" font-size="12" fill="#7f1d1d">Wish: I wish I had asked for help.</text><text x="56" y="152" font-size="12" fill="#7f1d1d">If only I had asked for help!</text><text x="56" y="182" font-size="12" font-weight="700" fill="#b91c1c">Formula: wish / if only + had + V3</text><rect x="400" y="52" width="320" height="150" rx="12" fill="#ffffff" stroke="#2563eb" stroke-width="2"/><rect x="400" y="52" width="320" height="30" rx="12" fill="#2563eb"/><text x="560" y="72" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">Present Wish (Şimdiki Zaman Dileği)</text><text x="416" y="104" font-size="12" fill="#1e3a8a">Fact: I am anxious about the exam.</text><text x="416" y="128" font-size="12" fill="#1e3a8a">Wish: I wish I weren\'t so anxious.</text><text x="416" y="152" font-size="12" fill="#1e3a8a">If only I felt calmer now!</text><text x="416" y="182" font-size="12" font-weight="700" fill="#1d4ed8">Formula: wish / if only + V2 / were</text><line x1="200" y1="202" x2="200" y2="226" stroke="#dc2626" stroke-width="2" stroke-dasharray="4 3"/><line x1="560" y1="202" x2="560" y2="226" stroke="#2563eb" stroke-width="2" stroke-dasharray="4 3"/><line x1="60" y1="235" x2="700" y2="235" stroke="#64748b" stroke-width="3"/><polygon points="700,228 716,235 700,242" fill="#64748b"/><circle cx="200" cy="235" r="8" fill="#dc2626"/><circle cx="560" cy="235" r="8" fill="#2563eb"/><text x="200" y="262" text-anchor="middle" font-size="12" font-weight="700" fill="#dc2626">PAST (yesterday, last year)</text><text x="560" y="262" text-anchor="middle" font-size="12" font-weight="700" fill="#2563eb">NOW (today, at the moment)</text><text x="380" y="288" text-anchor="middle" font-size="11" fill="#334155">Kural: Dilek cümlesinde zaman bir derece geriye kayar (Past Simple → Past Perfect, Present → Past Simple).</text></svg>', 'b2': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="16" fill="#f8fafc"/><text x="380" y="32" text-anchor="middle" font-size="16" font-weight="700" fill="#0f172a">Modal Perfects: Looking Back at the Past</text><rect x="24" y="52" width="228" height="200" rx="12" fill="#ffffff" stroke="#dc2626" stroke-width="2"/><rect x="24" y="52" width="228" height="32" rx="12" fill="#dc2626"/><text x="138" y="73" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">should (not) have + V3</text><text x="38" y="106" font-size="12" font-weight="700" fill="#991b1b">Criticism / Regret</text><text x="38" y="126" font-size="11" fill="#7f1d1d">Eleştiri ve pişmanlık</text><text x="38" y="156" font-size="12" fill="#334155">You shouldn\'t have</text><text x="38" y="174" font-size="12" fill="#334155">bottled up your anger.</text><text x="38" y="206" font-size="11" fill="#7f1d1d">Öfkeni içinde</text><text x="38" y="224" font-size="11" fill="#7f1d1d">tutmamalıydın.</text><rect x="266" y="52" width="228" height="200" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><rect x="266" y="52" width="228" height="32" rx="12" fill="#0284c7"/><text x="380" y="73" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">could have + V3</text><text x="280" y="106" font-size="12" font-weight="700" fill="#075985">Unused Chance / Ability</text><text x="280" y="126" font-size="11" fill="#0c4a6e">Kullanılmamış fırsat</text><text x="280" y="156" font-size="12" fill="#334155">You could have asked</text><text x="280" y="174" font-size="12" fill="#334155">me for help.</text><text x="280" y="206" font-size="11" fill="#0c4a6e">Benden yardım</text><text x="280" y="224" font-size="11" fill="#0c4a6e">isteyebilirdin (ama istemedin).</text><rect x="508" y="52" width="228" height="200" rx="12" fill="#ffffff" stroke="#16a34a" stroke-width="2"/><rect x="508" y="52" width="228" height="32" rx="12" fill="#16a34a"/><text x="622" y="73" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">needn\'t have + V3</text><text x="522" y="106" font-size="12" font-weight="700" fill="#166534">Unnecessary Action</text><text x="522" y="126" font-size="11" fill="#14532d">Gereksiz yere yapılmış eylem</text><text x="522" y="156" font-size="12" fill="#334155">You needn\'t have worried;</text><text x="522" y="174" font-size="12" fill="#334155">the test was easy.</text><text x="522" y="206" font-size="11" fill="#14532d">Endişelenmene gerek</text><text x="522" y="224" font-size="11" fill="#14532d">yoktu; sınav kolaydı.</text><rect x="120" y="264" width="520" height="26" rx="10" fill="#e2e8f0"/><text x="380" y="282" text-anchor="middle" font-size="12" font-weight="700" fill="#0f172a">Formula: modal + have + V3 (past participle)</text></svg>', 'b3': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="16" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="700" fill="#4c1d95">Third and Mixed Conditionals: Imagined Results</text><text x="40" y="62" font-size="13" font-weight="700" fill="#7c3aed">Third Conditional (past condition → past result)</text><rect x="40" y="72" width="300" height="62" rx="12" fill="#ffffff" stroke="#7c3aed" stroke-width="2"/><text x="190" y="96" text-anchor="middle" font-size="12" font-weight="700" fill="#5b21b6">If + Subject + had + V3</text><text x="190" y="119" text-anchor="middle" font-size="12" fill="#334155">If I had slept enough,</text><line x1="345" y1="103" x2="405" y2="103" stroke="#7c3aed" stroke-width="3"/><polygon points="405,96 420,103 405,110" fill="#7c3aed"/><rect x="425" y="72" width="300" height="62" rx="12" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/><text x="575" y="96" text-anchor="middle" font-size="12" font-weight="700" fill="#5b21b6">would / could have + V3</text><text x="575" y="119" text-anchor="middle" font-size="12" fill="#334155">I would have focused better.</text><text x="40" y="164" font-size="13" font-weight="700" fill="#d97706">Mixed Conditional (past condition → present result)</text><rect x="40" y="174" width="300" height="62" rx="12" fill="#ffffff" stroke="#d97706" stroke-width="2"/><text x="190" y="198" text-anchor="middle" font-size="12" font-weight="700" fill="#92400e">If + Subject + had + V3</text><text x="190" y="221" text-anchor="middle" font-size="12" fill="#334155">If I had chosen a quieter dorm,</text><line x1="345" y1="205" x2="405" y2="205" stroke="#d97706" stroke-width="3"/><polygon points="405,198 420,205 405,212" fill="#d97706"/><rect x="425" y="174" width="300" height="62" rx="12" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><text x="575" y="198" text-anchor="middle" font-size="12" font-weight="700" fill="#92400e">would + V1 (now)</text><text x="575" y="221" text-anchor="middle" font-size="12" fill="#334155">I would be more relaxed now.</text><rect x="40" y="252" width="685" height="34" rx="10" fill="#e2e8f0"/><text x="382" y="274" text-anchor="middle" font-size="11" fill="#0f172a">Wish bağlantısı: I wish I had slept enough = If I had slept enough, I would have focused better.</text></svg>', 'b4': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="16" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="700" fill="#0f172a">Psychology Vocabulary: Phobias and Personality Types</text><rect x="24" y="48" width="168" height="112" rx="12" fill="#ffffff" stroke="#dc2626" stroke-width="2"/><text x="108" y="76" text-anchor="middle" font-size="13" font-weight="700" fill="#b91c1c">Arachnophobia</text><text x="108" y="102" text-anchor="middle" font-size="11" fill="#334155">fear of spiders</text><text x="108" y="126" text-anchor="middle" font-size="11" fill="#7f1d1d">örümcek korkusu</text><rect x="206" y="48" width="168" height="112" rx="12" fill="#ffffff" stroke="#7c3aed" stroke-width="2"/><text x="290" y="76" text-anchor="middle" font-size="13" font-weight="700" fill="#6d28d9">Claustrophobia</text><text x="290" y="102" text-anchor="middle" font-size="11" fill="#334155">fear of closed spaces</text><text x="290" y="126" text-anchor="middle" font-size="11" fill="#4c1d95">kapalı alan korkusu</text><rect x="388" y="48" width="168" height="112" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><text x="472" y="76" text-anchor="middle" font-size="13" font-weight="700" fill="#0369a1">Acrophobia</text><text x="472" y="102" text-anchor="middle" font-size="11" fill="#334155">fear of heights</text><text x="472" y="126" text-anchor="middle" font-size="11" fill="#0c4a6e">yükseklik korkusu</text><rect x="570" y="48" width="168" height="112" rx="12" fill="#ffffff" stroke="#d97706" stroke-width="2"/><text x="654" y="76" text-anchor="middle" font-size="13" font-weight="700" fill="#b45309">Glossophobia</text><text x="654" y="102" text-anchor="middle" font-size="11" fill="#334155">fear of public speaking</text><text x="654" y="126" text-anchor="middle" font-size="11" fill="#92400e">topluluk önünde</text><text x="654" y="142" text-anchor="middle" font-size="11" fill="#92400e">konuşma korkusu</text><text x="380" y="188" text-anchor="middle" font-size="13" font-weight="700" fill="#0f172a">Personality Spectrum</text><rect x="60" y="198" width="213" height="24" rx="8" fill="#93c5fd"/><rect x="273" y="198" width="214" height="24" fill="#a7f3d0"/><rect x="487" y="198" width="213" height="24" rx="8" fill="#fcd34d"/><text x="166" y="215" text-anchor="middle" font-size="12" font-weight="700" fill="#1e3a8a">Introvert</text><text x="380" y="215" text-anchor="middle" font-size="12" font-weight="700" fill="#065f46">Ambivert</text><text x="593" y="215" text-anchor="middle" font-size="12" font-weight="700" fill="#92400e">Extrovert</text><text x="166" y="242" text-anchor="middle" font-size="11" fill="#334155">içe dönük: recharges alone</text><text x="380" y="242" text-anchor="middle" font-size="11" fill="#334155">dengeli: both sides</text><text x="593" y="242" text-anchor="middle" font-size="11" fill="#334155">dışa dönük: energized by people</text><text x="380" y="278" text-anchor="middle" font-size="11" fill="#475569">Key terms: self-esteem, procrastination, peer pressure, perfectionism, comfort zone</text></svg>', 'b5': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="16" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="700" fill="#065f46">Writing an Advice Letter: Five-Part Structure</text><rect x="20" y="56" width="132" height="176" rx="12" fill="#ffffff" stroke="#059669" stroke-width="2"/><circle cx="86" cy="56" r="14" fill="#059669"/><text x="86" y="61" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">1</text><text x="86" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#065f46">Greeting</text><text x="86" y="122" text-anchor="middle" font-size="11" fill="#334155">Dear Deniz,</text><text x="86" y="142" text-anchor="middle" font-size="11" fill="#334155">Thank you for</text><text x="86" y="160" text-anchor="middle" font-size="11" fill="#334155">your letter.</text><text x="86" y="208" text-anchor="middle" font-size="11" fill="#047857">Selamlama</text><rect x="166" y="56" width="132" height="176" rx="12" fill="#ffffff" stroke="#0284c7" stroke-width="2"/><circle cx="232" cy="56" r="14" fill="#0284c7"/><text x="232" y="61" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">2</text><text x="232" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#075985">Empathy</text><text x="232" y="122" text-anchor="middle" font-size="11" fill="#334155">I understand</text><text x="232" y="142" text-anchor="middle" font-size="11" fill="#334155">how stressful</text><text x="232" y="160" text-anchor="middle" font-size="11" fill="#334155">this must be.</text><text x="232" y="208" text-anchor="middle" font-size="11" fill="#0369a1">Empati</text><rect x="312" y="56" width="132" height="176" rx="12" fill="#ffffff" stroke="#7c3aed" stroke-width="2"/><circle cx="378" cy="56" r="14" fill="#7c3aed"/><text x="378" y="61" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">3</text><text x="378" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#5b21b6">Advice</text><text x="378" y="122" text-anchor="middle" font-size="11" fill="#334155">First of all,</text><text x="378" y="142" text-anchor="middle" font-size="11" fill="#334155">why don\'t you...?</text><text x="378" y="160" text-anchor="middle" font-size="11" fill="#334155">Moreover, I</text><text x="378" y="178" text-anchor="middle" font-size="11" fill="#334155">suggest + V-ing</text><text x="378" y="208" text-anchor="middle" font-size="11" fill="#6d28d9">Öneriler</text><rect x="458" y="56" width="132" height="176" rx="12" fill="#ffffff" stroke="#d97706" stroke-width="2"/><circle cx="524" cy="56" r="14" fill="#d97706"/><text x="524" y="61" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">4</text><text x="524" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#92400e">Encouragement</text><text x="524" y="122" text-anchor="middle" font-size="11" fill="#334155">Don\'t be too</text><text x="524" y="142" text-anchor="middle" font-size="11" fill="#334155">hard on yourself.</text><text x="524" y="160" text-anchor="middle" font-size="11" fill="#334155">You will get</text><text x="524" y="178" text-anchor="middle" font-size="11" fill="#334155">over this!</text><text x="524" y="208" text-anchor="middle" font-size="11" fill="#b45309">Cesaretlendirme</text><rect x="604" y="56" width="132" height="176" rx="12" fill="#ffffff" stroke="#db2777" stroke-width="2"/><circle cx="670" cy="56" r="14" fill="#db2777"/><text x="670" y="61" text-anchor="middle" font-size="13" font-weight="700" fill="#ffffff">5</text><text x="670" y="92" text-anchor="middle" font-size="13" font-weight="700" fill="#9d174d">Closing</text><text x="670" y="122" text-anchor="middle" font-size="11" fill="#334155">Best wishes,</text><text x="670" y="142" text-anchor="middle" font-size="11" fill="#334155">Take care,</text><text x="670" y="160" text-anchor="middle" font-size="11" fill="#334155">Yours, Aunt Elif</text><text x="670" y="208" text-anchor="middle" font-size="11" fill="#be185d">Kapanış</text><rect x="80" y="250" width="600" height="32" rx="10" fill="#d1fae5"/><text x="380" y="271" text-anchor="middle" font-size="11" fill="#065f46">Linking words: First of all, Secondly, In addition, Moreover, Finally, Most importantly</text></svg>', 'b6': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect width="760" height="300" rx="16" fill="#f8fafc"/><text x="380" y="30" text-anchor="middle" font-size="16" font-weight="700" fill="#0f172a">Reading Strategy: Finding Tone, Feelings and Regret</text><rect x="24" y="50" width="164" height="96" rx="12" fill="#ffffff" stroke="#2563eb" stroke-width="2"/><text x="106" y="74" text-anchor="middle" font-size="12" font-weight="700" fill="#1d4ed8">Step 1</text><text x="106" y="96" text-anchor="middle" font-size="12" fill="#334155">Find feeling words</text><text x="106" y="120" text-anchor="middle" font-size="11" fill="#64748b">devastated, relieved</text><rect x="208" y="50" width="164" height="96" rx="12" fill="#ffffff" stroke="#dc2626" stroke-width="2"/><text x="290" y="74" text-anchor="middle" font-size="12" font-weight="700" fill="#b91c1c">Step 2</text><text x="290" y="96" text-anchor="middle" font-size="12" fill="#334155">Spot regret forms</text><text x="290" y="120" text-anchor="middle" font-size="11" fill="#64748b">I wish I had, should have</text><rect x="392" y="50" width="164" height="96" rx="12" fill="#ffffff" stroke="#d97706" stroke-width="2"/><text x="474" y="74" text-anchor="middle" font-size="12" font-weight="700" fill="#b45309">Step 3</text><text x="474" y="96" text-anchor="middle" font-size="12" fill="#334155">Check linkers</text><text x="474" y="120" text-anchor="middle" font-size="11" fill="#64748b">however, although, but</text><rect x="576" y="50" width="164" height="96" rx="12" fill="#ffffff" stroke="#059669" stroke-width="2"/><text x="658" y="74" text-anchor="middle" font-size="12" font-weight="700" fill="#047857">Step 4</text><text x="658" y="96" text-anchor="middle" font-size="12" fill="#334155">Infer the tone</text><text x="658" y="120" text-anchor="middle" font-size="11" fill="#64748b">regretful, hopeful</text><polygon points="190,92 204,98 190,104" fill="#94a3b8"/><polygon points="374,92 388,98 374,104" fill="#94a3b8"/><polygon points="558,92 572,98 558,104" fill="#94a3b8"/><rect x="24" y="170" width="230" height="74" rx="12" fill="#fee2e2"/><text x="139" y="196" text-anchor="middle" font-size="13" font-weight="700" fill="#991b1b">Regretful</text><text x="139" y="220" text-anchor="middle" font-size="11" fill="#7f1d1d">if only, I wish I had + V3</text><rect x="265" y="170" width="230" height="74" rx="12" fill="#dcfce7"/><text x="380" y="196" text-anchor="middle" font-size="13" font-weight="700" fill="#166534">Hopeful</text><text x="380" y="220" text-anchor="middle" font-size="11" fill="#14532d">from now on, next time I will</text><rect x="506" y="170" width="230" height="74" rx="12" fill="#fef3c7"/><text x="621" y="196" text-anchor="middle" font-size="13" font-weight="700" fill="#92400e">Critical</text><text x="621" y="220" text-anchor="middle" font-size="11" fill="#78350f">you shouldn\'t have + V3</text><text x="380" y="276" text-anchor="middle" font-size="11" fill="#334155">İpucu: Zıtlık bağlacından sonraki cümle genellikle metnin asıl tonunu taşır.</text></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
